    ni = V(g, nearest.outputs['Index']); nk = _read(g, geo, 'st_cc_knot', ni)
    at = bounded(g, ni-g.math('GREATER_THAN', nk, s), 0., n-2.)
    start = _read(g, geo, 'st_cc_knot', at); span = g.math('MAXIMUM', 1e-12, _read(g, geo, 'st_cc_span', at))
    u = (s-start)/span
    p, a, b, c = [_vec(g, _read(g, geo, 'st_cc_'+key, at, 'FLOAT_VECTOR')) for key in ('p', 'a', 'b', 'c')]
    point = _add(p, _scale(_add(a, _scale(_add(b, _scale(c, u)), u)), u))
    velocity = _scale(_add(a, _scale(_add(_scale(b, 2.), _scale(c, 3.*u)), u)), g.math('DIVIDE', 1., span))
    acceleration = _scale(_add(_scale(b, 2.), _scale(c, 6.*u)), g.math('DIVIDE', 1., span*span))
    p0 = _vec(g, _read(g, geo, 'st_cc_p', 0, 'FLOAT_VECTOR'))
    t0 = _vec(g, _read(g, geo, 'st_cc_tangent', 0, 'FLOAT_VECTOR'))
