    velocity = _pick(g, before, t0, velocity)
    acceleration = _pick(g, before, [0., 0.], acceleration)
    if derivatives:jerk = _pick(g, before, [0., 0.], _scale(c, g.math('DIVIDE',6.,span**3.)))
    speed = _length(g, velocity); tangent = _unit(g, velocity)
