def _jet(g, path, parameter, offset, *, curvature=False, polyline=False,frame_derivatives=False):
    n = g.node('GeometryNodeGroup', 'Analytic offset curve evaluation'); n.node_tree = evaluate_path(curvature=curvature, polyline=polyline,frame_derivatives=frame_derivatives)
    for key, val in (('Path', path), ('Parameter', parameter), ('Offset', offset)): g.bind(val, n.inputs[key])
    return {key: V(g, socket) for key, socket in n.outputs.items()}


def _circle_jet(g, path, parameter, offset, *, polyline=False, curb_offset=0., radius_offset=0.):
    """Circle-center locus, distinct from a mitered pavement offset.

    On an Exact leg the physical curb is a straight line interpolating its
    endpoint miters. A tangent circle center is displaced normally from THAT
    line. Applying the miter frame to the radius as well gives a different,
    generally non-tangent circle. Smooth-mode arithmetic remains unchanged.
    """
    result = _jet(g, path, parameter, offset)
    if polyline:
        exact = _read(g, path, 'st_cc_polyline', 0, 'BOOLEAN')
        curb = _jet(g, path, parameter, curb_offset, polyline=True)
        center = _add(_vec(g, curb['Center']), _scale(_right(_vec(g, curb['Tangent'])), radius_offset))
        result['Center'] = choose(g, exact, g.xyz(*center), result['Center'], 'VECTOR')
        for key in ('Derivative', 'Jacobian'):
            result[key] = choose(g, exact, curb[key], result[key], 'VECTOR' if key == 'Derivative' else 'FLOAT')
        result['Curb'] = curb['Center']
    return result


def _samples(g, path, length, lower, offset, samples, *, polyline=False, curb_offset=0., radius_offset=0.):
    index = V(g, g.node('GeometryNodeInputIndex').outputs[0])
    uniform = g.setpos(_line(g, samples+1.), g.xyz(lower+(length-lower)*index/samples))
    join = g.node('GeometryNodeJoinGeometry', 'Include every original knot in the seed search')
    g.bind(uniform, join.inputs['Geometry']); g.bind(path, join.inputs['Geometry'])
    merge = g.node('GeometryNodeMergeByDistance'); merge.inputs['Distance'].default_value = 1e-6
    g.bind(join.outputs['Geometry'], merge.inputs['Geometry'])
    sort = g.node('GeometryNodeSortElements'); sort.domain = 'POINT'
    g.bind(merge.outputs['Geometry'], sort.inputs['Geometry']); g.bind(g.separate(g.position())[0], sort.inputs['Sort Weight'])
    geo = _store(g, sort.outputs['Geometry'], 'st_cc_sample_s', g.separate(g.position())[0])
    circle = lambda s: _circle_jet(g, path, s, offset, polyline=polyline,
                                  curb_offset=curb_offset, radius_offset=radius_offset)
    s = named(g, 'st_cc_sample_s'); center = circle(s)['Center']
    if polyline:
        # A normal jumps at an authored bend. Keep independent start/end
        # values for every seed interval so no chord bridges that jump.
        following = _read(g, geo, 'st_cc_sample_s', g.math('MINIMUM', index+1., _count(g, geo)-1.))
        midpoint = circle((s+following)*.5); half = (following-s)*.5
        exact = _read(g, path, 'st_cc_polyline', 0, 'BOOLEAN')
        displacement = _scale(_vec(g, midpoint['Derivative']), half)
        center = choose(g, exact, g.xyz(*_sub(_vec(g, midpoint['Center']), displacement)), center, 'VECTOR')
        end = choose(g, exact, g.xyz(*_add(_vec(g, midpoint['Center']), displacement)), circle(following)['Center'], 'VECTOR')
        geo = _store(g, geo, 'st_cc_sample_c_end', end, 'FLOAT_VECTOR')
    return _store(g, geo, 'st_cc_sample_c', center, 'FLOAT_VECTOR')


def build(*, prepared_paths=False, polyline=False, stop_on_fixed_point=False, filter_seed_pairs=False):
    if polyline and not prepared_paths:
        raise ValueError('Exact corner evaluation requires already prepared mode-aware paths')
    name = PREFIX+'fixed-radius candidates v2'
    if prepared_paths: name += ' / Prepared paths v2'
    if polyline: name += ' / Exact or smooth curb contacts v1'
    if stop_on_fixed_point:name+=' / Exact fixed-point reuse v1'
    if filter_seed_pairs:name+=' / Filter before seed interpolation v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = Graph(name)
    for side in ('A', 'B'):
        g.socket('Path '+side, 'NodeSocketGeometry'); g.socket('Reverse '+side, 'NodeSocketBool', default=False)
        g.socket('Width '+side, 'NodeSocketFloat', default=6.); g.socket('Offset '+side, 'NodeSocketFloat', default=0.)
        if prepared_paths:
            g.socket('Length '+side, 'NodeSocketFloat')
            g.socket('Valid '+side, 'NodeSocketBool', default=False)
            g.socket('Weighted '+side, 'NodeSocketBool', default=False)
    g.socket('Radius', 'NodeSocketFloat', default=3.)
    g.socket('Seed Intervals', 'NodeSocketInt', default=96)
    g.socket('Backward Extensions', 'NodeSocketBool', default=True)
    for key, kind in (('Candidates', 'NodeSocketGeometry'), ('Inputs Valid', 'NodeSocketBool'),
                      ('Candidate Count', 'NodeSocketInt'), ('Seed Count', 'NodeSocketInt')):
        g.socket(key, kind, 'OUTPUT')
    inp = g.node('NodeGroupInput'); paths, lengths, checks, weighted_paths = [], [], [], []
    widths = [V(g, inp.outputs['Width '+side]) for side in ('A', 'B')]
    offsets = [choose(g, inp.outputs['Reverse '+side], -V(g, inp.outputs['Offset '+side]), inp.outputs['Offset '+side]) for side in ('A', 'B')]
    radius = V(g, inp.outputs['Radius']); samples = V(g, inp.outputs['Seed Intervals'])
    for side in ('A', 'B'):
        if prepared_paths:
            paths.append(inp.outputs['Path '+side])
            lengths.append(V(g, inp.outputs['Length '+side]))
            checks.append(V(g, inp.outputs['Valid '+side]))
            weighted_paths.append(inp.outputs['Weighted '+side])
            continue
        n = g.node('GeometryNodeGroup', 'Original ordered '+side+' source chain'); n.node_tree = prepare_path()
        g.bind(inp.outputs['Path '+side], n.inputs['Geometry']); g.bind(inp.outputs['Reverse '+side], n.inputs['Reverse'])
        for key in ('Width', 'Offset'): g.bind(inp.outputs[key+' '+side], n.inputs[key])
        paths.append(n.outputs['Geometry']); lengths.append(V(g, n.outputs['Length'])); checks.append(V(g, n.outputs['Valid']))
        weighted_paths.append(n.outputs['Weighted'])
    ta, tb = [_vec(g, _jet(g, path, 0., 0.)['Tangent']) for path in paths]
    side = choose(g, g.math('LESS_THAN', _cross(ta, tb), 0.), -1., 1.)
    ds = [offsets[0]-widths[0]*.5-side*radius, offsets[1]+widths[1]*.5+side*radius]
    curbs = [offsets[0]-widths[0]*.5, offsets[1]+widths[1]*.5]
    radius_offsets = [-side*radius, side*radius]
    def jets_at(parameters):
        return [_circle_jet(g, path, s, d, polyline=polyline, curb_offset=curb, radius_offset=shift)
                for path, s, d, curb, shift in zip(paths, parameters, ds, curbs, radius_offsets)]
    lower = choose(g, inp.outputs['Backward Extensions'], -4.*(g.math('MAXIMUM', *widths)+2.*radius), 0.)
    tables = [_samples(g, path, length, lower, d, bounded(g, samples, 16., 256.),
                       polyline=polyline, curb_offset=curb, radius_offset=shift)
              for path, length, d, curb, shift in zip(paths, lengths, ds, curbs, radius_offsets)]
    na, nb = [_count(g, t)-1. for t in tables]; total = na*nb
    valid = checks[0]*checks[1]*g.math('GREATER_THAN', radius, 0.)
    for width in widths: valid = valid*g.math('GREATER_THAN', width, 0.)
    valid = valid*g.math('GREATER_THAN', samples, 15.5)*g.math('LESS_THAN', samples, 256.5)
    valid = valid*g.math('LESS_THAN', total, MAX_PAIRS+.5)
    index = V(g, g.node('GeometryNodeInputIndex').outputs[0])
    pairs = _line(g, choose(g, valid, total, 1, 'INT'))
    indices = [g.math('FLOOR', index/nb), g.math('MODULO', index, nb)]
    def chord_crossings(indices):
        endpoints = [[_vec(g, _read(g, table, 'st_cc_sample_c', at+step, 'FLOAT_VECTOR')) for step in (0., 1.)] for table, at in zip(tables, indices)] if not polyline else [
            [_vec(g, _read(g, table, key, at, 'FLOAT_VECTOR')) for key in ('st_cc_sample_c', 'st_cc_sample_c_end')]
            for table, at in zip(tables, indices)]
        a, b = endpoints; va, vb = _sub(a[1], a[0]), _sub(b[1], b[0]); delta = _sub(b[0], a[0])
        determinant = _cross(va, vb)
        return determinant, _cross(delta, vb)/determinant, _cross(delta, va)/determinant
    determinant, ua, ub = chord_crossings(indices)
    hit = valid*g.math('GREATER_THAN', g.math('ABSOLUTE', determinant), 1e-8)
    for u in (ua, ub): hit = hit*g.math('GREATER_THAN', u, -1e-6)*g.math('LESS_THAN', u, 1.+1e-6)
    if filter_seed_pairs:
        # Keep the identical all-pairs crossing predicate and original order.
        # Store just the integer pair index before filtering. Only surviving
        # crossings need expensive seed-parameter interpolation; reconstruct
        # its original indices instead of using compacted point indices.
        pairs = _store(g, pairs, '_cc_seed_pair', index, 'INT')
        pairs = _select(g, pairs, hit)
        original_index = named(g, '_cc_seed_pair', 'INT')
        indices = [g.math('FLOOR', original_index/nb), g.math('MODULO', original_index, nb)]
        _, ua, ub = chord_crossings(indices)
    # Both variants interpolate with the same original indices and arithmetic.
    for key, table, at, u in zip(('a', 'b'), tables, indices, (ua, ub)):
        s0, s1 = [_read(g, table, 'st_cc_sample_s', at+step) for step in (0., 1.)]
        pairs = _store(g, pairs, 'st_cc_s'+key, s0+u*(s1-s0))
    if filter_seed_pairs:
        remove = g.node('GeometryNodeRemoveAttribute', 'Remove private seed-pair transport')
        g.bind(pairs, remove.inputs['Geometry']); remove.inputs['Name'].default_value = '_cc_seed_pair'
        pairs = remove.outputs['Geometry']
    else:
        pairs = _select(g, pairs, hit)
    seed_count = _count(g, pairs)
    ri = g.node('GeometryNodeRepeatInput', 'Damped Newton iterations'); ro = g.node('GeometryNodeRepeatOutput')
    if stop_on_fixed_point:ro.repeat_items.new('BOOLEAN','Fixed Point')
    ri.pair_with_output(ro); ri.inputs['Iterations'].default_value = 12; g.bind(pairs, ri.inputs['Geometry'])
    geo = ri.outputs['Geometry']; sa, sb = named(g, 'st_cc_sa'), named(g, 'st_cc_sb')
    ja, jb = jets_at((sa, sb))
    f = _sub(_vec(g, ja['Center']), _vec(g, jb['Center']))
    va, vb = _vec(g, ja['Derivative']), _vec(g, jb['Derivative']); determinant = _cross(va, vb)
    da, db = -_cross(f, vb)/determinant, -_cross(f, va)/determinant
    trust = g.math('MAXIMUM', 1., g.math('MAXIMUM', *lengths)/32.)
    scale = g.math('MINIMUM', 1., trust/g.math('MAXIMUM', 1e-12, g.math('MAXIMUM', g.math('ABSOLUTE', da), g.math('ABSOLUTE', db))))
    safe = g.math('GREATER_THAN', g.math('ABSOLUTE', determinant), 1e-8)
    for key, val in (('da', da*scale*safe), ('db', db*scale*safe), ('error', _length(g, f)), ('best_a', sa), ('best_b', sb)):
        geo = _store(g, geo, 'st_cc_'+key, val)
    li = g.node('GeometryNodeRepeatInput', 'Bounded residual-decreasing line search'); lo = g.node('GeometryNodeRepeatOutput')
    li.pair_with_output(lo); li.inputs['Iterations'].default_value = 6; g.bind(geo, li.inputs['Geometry'])
    factor = g.math('POWER', .5, V(g, li.outputs['Iteration']))
    trial = [bounded(g, named(g, 'st_cc_s'+key)+factor*named(g, 'st_cc_d'+key), lower, length) for key, length in zip(('a', 'b'), lengths)]
    jets = jets_at(trial)
    error = _length(g, _sub(_vec(g, jets[0]['Center']), _vec(g, jets[1]['Center'])))
    improve = g.math('LESS_THAN', error, named(g, 'st_cc_error'))
    trial_geo = li.outputs['Geometry']
    # Freeze acceptance before changing the residual used by its field.
    trial_geo = _store(g, trial_geo, 'st_cc_accept', improve, 'BOOLEAN')
    for key, val in zip(('best_a', 'best_b', 'error'), (*trial, error)):
        trial_geo = _store(g, trial_geo, 'st_cc_'+key, choose(g, named(g, 'st_cc_accept', 'BOOLEAN'), val, named(g, 'st_cc_'+key)))
    g.bind(trial_geo, lo.inputs['Geometry'])
    geo = lo.outputs['Geometry']
    if stop_on_fixed_point:
        # The outer iteration index is not used by the Newton map. If an
        # entire step leaves every parameter unchanged, the same deterministic
        # step cannot change the following result. Keep this completed step's
        # metadata too; do not skip based on a residual tolerance.
        unchanged=True
        for key in ('a','b'):
            same=g.node('FunctionNodeCompare','Exact unchanged Newton parameter '+key)
            same.data_type='FLOAT';same.operation='EQUAL'
            g.bind(named(g,'st_cc_s'+key),next(s for s in same.inputs if s.name=='A' and s.type=='VALUE'))
            g.bind(named(g,'st_cc_best_'+key),next(s for s in same.inputs if s.name=='B' and s.type=='VALUE'))
            same.inputs['Epsilon'].default_value=0.
            unchanged=V(g,same.outputs['Result'])*unchanged
        stationary=_stat(g,geo,unchanged)
    for key in ('a', 'b'): geo = _store(g, geo, 'st_cc_s'+key, named(g, 'st_cc_best_'+key))
    if stop_on_fixed_point:
        frozen=ri.outputs['Fixed Point']
        # Lazy geometry/boolean switches avoid evaluating the expensive step
        # after the fixed point has been established. Final certification and
        # root merging below still run on the identical completed geometry.
        geo=choose(g,frozen,ri.outputs['Geometry'],geo,'GEOMETRY')
        g.bind(choose(g,frozen,True,stationary,'BOOLEAN'),ro.inputs['Fixed Point'])
    g.bind(geo, ro.inputs['Geometry']); geo = ro.outputs['Geometry']
    if prepared_paths:
        # A converged endpoint root can retain a tiny negative parameter when
        # float32 residuals underflow to zero (e.g. -7.7e-25 m). Downstream
        # original-span selection correctly requires nonnegative contacts.
        # Reevaluate such roots at the exact endpoint BEFORE certification,
        # rather than relaxing that selection or changing accepted radii.
        for key in ('a', 'b'):
            station = named(g, 'st_cc_s'+key)
            residue = g.math('LESS_THAN', station, 0.)*g.math(
                'GREATER_THAN', station, -ENDPOINT_PARAMETER_EPSILON)
            geo = _store(g, geo, 'st_cc_s'+key, choose(g, residue, 0., station))
    sa, sb = named(g, 'st_cc_sa'), named(g, 'st_cc_sb')
    jets = jets_at((sa, sb))
    centers = [_vec(g, j['Center']) for j in jets]; tangents = [_vec(g, j['Tangent']) for j in jets]
    error = _length(g, _sub(*centers)); center = _scale(_add(*centers), .5)
    angle = g.math('ARCTAN2', _cross(*tangents), _dot(*tangents))
    angle = choose(g, g.math('LESS_THAN', angle, 0.), angle+6.283185307179586, angle)
    sweep = angle-3.141592653589793
    accepted = valid*g.math('LESS_THAN', error, TOLERANCE)*g.math('LESS_THAN', side*sweep, 1e-6)
    contacts = []
    for at, (j, t, s) in enumerate(zip(jets, tangents, (sa, sb))):
        contact = _add(_vec(g, j['Point']), _scale(_right(t), offsets[at]+(-.5 if at == 0 else .5)*widths[at]))
        if polyline:
            exact = _read(g, paths[at], 'st_cc_polyline', 0, 'BOOLEAN')
            contact = _pick(g, exact, _vec(g, j['Curb']), contact)
        contacts.append(contact)
        accepted = accepted*g.math('GREATER_THAN', s, lower+1e-4)*g.math('GREATER_THAN', j['Jacobian'], .02)*g.math('GREATER_THAN', j['Speed'], 1e-5)
        accepted = accepted*g.math('LESS_THAN', g.math('ABSOLUTE', _length(g, _sub(contact, center))-radius), TOLERANCE)
    radial = _sub(contacts[0], center)
    cosine, sine = g.math('COSINE', sweep), g.math('SINE', sweep)
    arc_end = _add(center, [cosine*radial[0]-sine*radial[1], sine*radial[0]+cosine*radial[1]])
    accepted = accepted*g.math('LESS_THAN', _length(g, _sub(arc_end, contacts[1])), 2.*TOLERANCE)
    for key, value, kind in (('center', g.xyz(*center), 'FLOAT_VECTOR'), ('contact_a', g.xyz(*contacts[0]), 'FLOAT_VECTOR'),
                             ('contact_b', g.xyz(*contacts[1]), 'FLOAT_VECTOR'), ('sweep', sweep, 'FLOAT'),
                             ('residual', error, 'FLOAT'), ('radius', radius, 'FLOAT')):
        geo = _store(g, geo, 'st_cc_'+key, value, kind)
    for key, weighted in zip(('weighted_a', 'weighted_b'), weighted_paths):
        geo = _store(g, geo, 'st_cc_'+key, weighted, 'BOOLEAN')
    geo = _select(g, geo, accepted)
    # Merge duplicate numerical roots in parameter space, not nearby circles
    # with distinct provenance. Preserve every distinct candidate for the caller.
    geo = g.setpos(geo, g.xyz(named(g, 'st_cc_sa'), named(g, 'st_cc_sb')))
    merge = g.node('GeometryNodeMergeByDistance', 'Coalesce duplicate roots only'); merge.inputs['Distance'].default_value = 1e-4
    g.bind(geo, merge.inputs['Geometry']); geo = g.setpos(merge.outputs['Geometry'], named(g, 'st_cc_center', 'FLOAT_VECTOR'))
    out = g.node('NodeGroupOutput'); g.bind(geo, out.inputs['Candidates'])
    g.bind(valid, out.inputs['Inputs Valid']); g.bind(_count(g, geo), out.inputs['Candidate Count']); g.bind(seed_count, out.inputs['Seed Count'])
    return g.g
